CREATE OR REPLACE FUNCTION public.ajustar_pieza (
  _id_pieza     integer,
  _id_empresa   integer,
  _id_usuario   integer,
  _peso         numeric,
  _costo        numeric,
  _precio_venta numeric,
  _nota         text
)
  RETURNS void
  LANGUAGE plpgsql
  AS $function$
DECLARE v_ant piezas_inventario;
BEGIN
  SELECT * INTO v_ant FROM piezas_inventario
   WHERE id = _id_pieza AND id_empresa = _id_empresa FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pieza % no encontrada', _id_pieza; END IF;
  IF v_ant.estado = 'vendida' THEN
    RAISE EXCEPTION 'No se puede ajustar una pieza vendida (id %)', _id_pieza;
  END IF;
  IF _peso IS NOT NULL AND _peso <= 0 THEN RAISE EXCEPTION 'peso debe ser > 0'; END IF;

  UPDATE piezas_inventario
     SET peso         = coalesce(_peso, peso),
         costo        = coalesce(_costo, costo),
         precio_venta = coalesce(_precio_venta, precio_venta),
         nota         = coalesce(_nota, nota)
   WHERE id = _id_pieza;

  INSERT INTO movimientos_piezas (id_pieza, id_empresa, tipo, estado_anterior, estado_nuevo, id_usuario, notas)
  VALUES (_id_pieza, _id_empresa, 'ajuste', v_ant.estado, v_ant.estado, _id_usuario,
          format('ajuste: peso %s->%s, costo %s->%s, precio %s->%s. %s',
                 v_ant.peso, coalesce(_peso, v_ant.peso),
                 v_ant.costo, coalesce(_costo, v_ant.costo),
                 v_ant.precio_venta, coalesce(_precio_venta, v_ant.precio_venta),
                 coalesce(_nota,'')));
END;
$function$;

CREATE OR REPLACE FUNCTION public.asignarclientegenerico()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$declare _id_cliente int;
begin
 --seleccionamos el id del cliente generico
 select id into _id_cliente from clientes_proveedores where id_empresa = new.id_empresa and tipo='-';
-- editamos el cliente generico
 update ventas
 set id_cliente = _id_cliente  where id_cliente is null and id_empresa=new.id_empresa;
 return new;
end$function$;

CREATE OR REPLACE FUNCTION public.buscarproductos (
  _id_empresa integer,
  buscador    text
)
  RETURNS TABLE (
    id                  integer,
    nombre              text,
    precio_venta        numeric,
    precio_compra       numeric,
    id_categoria        integer,
    sevende_por         text,
    codigo_barras       text,
    codigo_interno      text,
    id_empresa          integer,
    maneja_inventarios  boolean,
    maneja_multiprecios boolean,
    p_venta             text,
    p_compra            text,
    categoria           text
  )
  LANGUAGE sql
  AS $function$
select p.id,
 p.nombre,p.precio_venta,p.precio_compra,p.id_categoria,p.sevende_por,p.codigo_barras,p.codigo_interno,p.id_empresa,p.maneja_inventarios,p.maneja_multiprecios,concat(e.simbolo_moneda,' ', p.precio_venta) as p_venta,concat(e.simbolo_moneda,' ', p.precio_compra) as p_compra,c.nombre as categoria
  from productos as p inner join empresa as e on e.id=p.id_empresa
  inner join categorias as c on c.id=p.id_categoria
  where (LOWER(p.nombre) LIKE '%' || LOWER(buscador) || '%'
    OR LOWER(p.codigo_barras) LIKE '%' || LOWER(buscador) || '%'
    OR LOWER(p.codigo_interno) LIKE '%' || LOWER(buscador) || '%')
    AND p.id_empresa = _id_empresa
    ORDER BY p.nombre ASC
    LIMIT 10;
$function$;

CREATE OR REPLACE FUNCTION public.buscarproductoslectora (
  _id_empresa integer,
  buscador    text
)
  RETURNS TABLE (
    id                  integer,
    nombre              text,
    precio_venta        numeric,
    precio_compra       numeric,
    id_categoria        integer,
    sevende_por         text,
    codigo_barras       text,
    codigo_interno      text,
    id_empresa          integer,
    maneja_inventarios  boolean,
    maneja_multiprecios boolean,
    p_venta             text,
    p_compra            text,
    categoria           text
  )
  LANGUAGE sql
  AS $function$
select p.id,
 p.nombre,p.precio_venta,p.precio_compra,p.id_categoria,p.sevende_por,p.codigo_barras,p.codigo_interno,p.id_empresa,p.maneja_inventarios,p.maneja_multiprecios,concat(e.simbolo_moneda,' ', p.precio_venta) as p_venta,concat(e.simbolo_moneda,' ', p.precio_compra) as p_compra,c.nombre as categoria
  from productos as p inner join empresa as e on e.id=p.id_empresa
  inner join categorias as c on c.id=p.id_categoria
  where
    ( LOWER(p.codigo_barras) = LOWER(buscador)
    OR LOWER(p.codigo_interno) = LOWER(buscador))
    AND p.id_empresa = _id_empresa;
$function$;

CREATE OR REPLACE FUNCTION public.buscarusuariosasignados (
  _id_empresa integer,
  buscador    text
)
  RETURNS TABLE (
    id_asignacion integer,
    id_usuario    integer,
    usuario       text,
    sucursal      text,
    caja          text,
    rol           text,
    email         text,
    estadouser    text
  )
  LANGUAGE sql
  AS $function$
select asignacion_sucursal.id as id_asignacion,
 usuarios.id as id_usuario,
  usuarios.nombres as usuario,
sucursales.nombre as sucursal, 
caja.descripcion as caja,
 roles.nombre as rol , 
 usuarios.correo as email , 
 usuarios.estado as estadouser 
 from asignacion_sucursal 
inner join sucursales on asignacion_sucursal.id_sucursal = sucursales.id
inner join usuarios on asignacion_sucursal.id_usuario = usuarios.id
inner join roles on usuarios.id_rol = roles.id
inner join caja on asignacion_sucursal.id_caja = caja.id
  where LOWER(usuarios.nombres) LIKE '%' || LOWER(buscador) || '%' and sucursales.id_empresa=_id_empresa and roles.nombre!='superadmin' ;
$function$;

CREATE OR REPLACE FUNCTION public.confirmar_venta (
  _id_venta            integer,
  _id_usuario          integer,
  _vuelto              numeric,
  _id_tipo_comprobante integer,
  _serie               character varying,
  _id_sucursal         integer,
  _id_cliente          integer,
  _fecha               timestamp without time zone,
  _monto_total         numeric
)
  RETURNS SETOF public.ventas
  LANGUAGE plpgsql
  AS $function$
DECLARE
    nuevo_comprobante TEXT;
BEGIN
  -- Generar número de comprobante automáticamente con el ID del tipo de comprobante
  select generar_nro_comprobante(_id_tipo_comprobante, _serie, _id_sucursal)
  INTO nuevo_comprobante;
   -- Actualizar la venta existente con el número de comprobante, cliente y estado confirmado
  UPDATE ventas
  SET 
      estado = 'confirmada',
      nro_comprobante = nuevo_comprobante,
      id_usuario = _id_usuario,
      vuelto = _vuelto,
      id_cliente = _id_cliente,
      fecha = _fecha,
      monto_total = _monto_total
      WHERE id = _id_venta;
       RETURN QUERY SELECT * FROM ventas WHERE id = _id_venta;
END; 
$function$;

CREATE OR REPLACE FUNCTION public.contarproductosporauth (
  _id_auth text
)
  RETURNS integer
  LANGUAGE sql
  AS $function$
  select count(p.id)
  from productos p
  inner join empresa e on e.id = p.id_empresa
  where e.id_auth = _id_auth;
$function$;

CREATE OR REPLACE FUNCTION public.crear_pieza (
  _id_variante  integer,
  _id_empresa   integer,
  _id_almacen   integer,
  _id_usuario   integer,
  _peso         numeric,
  _costo        numeric,
  _precio_venta numeric,
  _nota         text
)
  RETURNS SETOF public.piezas_inventario
  LANGUAGE plpgsql
  AS $function$
DECLARE r public.piezas_inventario;
BEGIN
  FOR r IN
    SELECT * FROM public.crear_piezas_masivo(
      _id_variante, _id_empresa, _id_almacen, _id_usuario,
      jsonb_build_array(jsonb_build_object(
        'peso', _peso, 'costo', coalesce(_costo,0),
        'precio_venta', _precio_venta, 'cantidad', 1))
    )
  LOOP
    IF _nota IS NOT NULL AND btrim(_nota) <> '' THEN
      UPDATE piezas_inventario SET nota = _nota WHERE id = r.id;
      r.nota := _nota;
    END IF;
    RETURN NEXT r;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.crear_piezas_masivo (
  _id_variante integer,
  _id_empresa  integer,
  _id_almacen  integer,
  _id_usuario  integer,
  _lineas      jsonb
)
  RETURNS SETOF public.piezas_inventario
  LANGUAGE plpgsql
  AS $function$
DECLARE
  v_prefijo    text;
  v_id_producto bigint;
  v_last       bigint;
  v_total      int := 0;
  v_counter    bigint;
  v_linea      jsonb;
  v_cant       int;
  v_peso       numeric;
  v_costo      numeric;
  v_precio     numeric;
  i            int;
  v_id         bigint;
  v_sku        text;
  v_barcode    text;
  v_estado_ant text;
  v_ids        bigint[] := '{}';
BEGIN
  IF _lineas IS NULL OR jsonb_typeof(_lineas) <> 'array' OR jsonb_array_length(_lineas) = 0 THEN
    RAISE EXCEPTION 'Se requiere al menos una línea de piezas';
  END IF;

  SELECT id_producto, sku_prefijo
    INTO v_id_producto, v_prefijo
    FROM producto_variantes
   WHERE id = _id_variante AND id_empresa = _id_empresa
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Variante % no encontrada para la empresa %', _id_variante, _id_empresa;
  END IF;
  IF v_prefijo IS NULL THEN
    RAISE EXCEPTION 'La variante % no tiene prefijo de SKU configurado', _id_variante;
  END IF;

  -- Validar líneas y contar el total de piezas a crear.
  FOR v_linea IN SELECT * FROM jsonb_array_elements(_lineas) LOOP
    v_cant   := coalesce((v_linea->>'cantidad')::int, 0);
    v_peso   := (v_linea->>'peso')::numeric;
    v_costo  := coalesce((v_linea->>'costo')::numeric, 0);
    v_precio := (v_linea->>'precio_venta')::numeric;
    IF v_cant < 1 THEN RAISE EXCEPTION 'cantidad debe ser >= 1 en cada línea'; END IF;
    IF v_peso IS NULL OR v_peso <= 0 THEN RAISE EXCEPTION 'peso debe ser > 0 en cada línea'; END IF;
    IF v_precio IS NULL OR v_precio < 0 THEN RAISE EXCEPTION 'precio_venta inválido en una línea'; END IF;
    IF v_costo < 0 THEN RAISE EXCEPTION 'costo inválido en una línea'; END IF;
    v_total := v_total + v_cant;
  END LOOP;

  -- Reservar el rango de correlativos de una sola vez (atómico bajo el lock).
  UPDATE producto_variantes
     SET ultimo_correlativo = ultimo_correlativo + v_total,
         updated_at = now()
   WHERE id = _id_variante
   RETURNING ultimo_correlativo INTO v_last;
  v_counter := v_last - v_total + 1;

  -- Crear cada pieza.
  FOR v_linea IN SELECT * FROM jsonb_array_elements(_lineas) LOOP
    v_cant   := (v_linea->>'cantidad')::int;
    v_peso   := (v_linea->>'peso')::numeric;
    v_costo  := coalesce((v_linea->>'costo')::numeric, 0);
    v_precio := (v_linea->>'precio_venta')::numeric;

    FOR i IN 1..v_cant LOOP
      v_sku     := v_prefijo || '-' || lpad(v_counter::text, 4, '0');
      v_barcode := public.joyeria_ean13(_id_empresa, nextval('public.joyeria_barcode_seq'));

      INSERT INTO piezas_inventario (
        id_variante, id_producto, id_empresa, id_almacen,
        sku, barcode, peso, costo, precio_venta, estado
      ) VALUES (
        _id_variante, v_id_producto, _id_empresa, _id_almacen,
        v_sku, v_barcode, v_peso, v_costo, v_precio, 'disponible'
      )
      RETURNING id INTO v_id;

      INSERT INTO movimientos_piezas (
        id_pieza, id_empresa, tipo, estado_nuevo, id_usuario, notas
      ) VALUES (
        v_id, _id_empresa, 'entrada', 'disponible', _id_usuario, 'alta masiva'
      );

      v_ids := v_ids || v_id;
      v_counter := v_counter + 1;
    END LOOP;
  END LOOP;

  RETURN QUERY SELECT * FROM piezas_inventario WHERE id = ANY(v_ids) ORDER BY id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.crear_producto_joyeria (
  _nombre       text,
  _descripcion  text,
  _id_categoria integer,
  _id_marca     integer,
  _id_empresa   integer
)
  RETURNS integer
  LANGUAGE plpgsql
  AS $function$
DECLARE nuevo_id int;
BEGIN
  IF _nombre IS NULL OR btrim(_nombre) = '' THEN
    RAISE EXCEPTION 'El nombre del producto es obligatorio';
  END IF;

  PERFORM 1 FROM productos WHERE nombre = _nombre AND id_empresa = _id_empresa;
  IF FOUND THEN
    RAISE EXCEPTION 'Nombre de producto duplicado';
  END IF;

  INSERT INTO productos (
    nombre, descripcion, precio_venta, precio_compra, id_categoria, id_marca,
    id_empresa, sevende_por, maneja_inventarios, maneja_multiprecios, es_joyeria
  ) VALUES (
    _nombre, _descripcion, 0, 0, _id_categoria, _id_marca,
    _id_empresa, 'unidad', false, false, true
  )
  RETURNING id INTO nuevo_id;

  RETURN nuevo_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.crear_variante (
  _id_producto            integer,
  _id_empresa             integer,
  _material               text,
  _pureza                 text,
  _sku_prefijo            text,
  _precio_venta_sugerido  numeric,
  _precio_compra_sugerido numeric
)
  RETURNS integer
  LANGUAGE plpgsql
  AS $function$
DECLARE
  v_prefijo_base text;
  v_prefijo      text;
  v_nombre_prod  text;
  v_intento      int := 0;
  nuevo_id       int;
BEGIN
  IF _material IS NULL OR btrim(_material) = '' THEN
    RAISE EXCEPTION 'El material de la variante es obligatorio';
  END IF;

  IF _sku_prefijo IS NOT NULL AND btrim(_sku_prefijo) <> '' THEN
    v_prefijo_base := upper(regexp_replace(_sku_prefijo, '[^A-Za-z0-9]', '', 'g'));
  ELSE
    SELECT nombre INTO v_nombre_prod FROM productos WHERE id = _id_producto;
    v_prefijo_base :=
      upper(substr(regexp_replace(coalesce(v_nombre_prod,'PRD'), '[^A-Za-z0-9]', '', 'g'), 1, 3))
      || upper(regexp_replace(coalesce(_pureza,''), '[^A-Za-z0-9]', '', 'g'));
    IF v_prefijo_base = '' THEN v_prefijo_base := 'VAR'; END IF;
  END IF;

  LOOP
    v_prefijo := CASE WHEN v_intento = 0 THEN v_prefijo_base
                      ELSE v_prefijo_base || v_intento::text END;
    BEGIN
      INSERT INTO producto_variantes (
        id_producto, id_empresa, material, pureza, sku_prefijo,
        precio_venta_sugerido, precio_compra_sugerido
      ) VALUES (
        _id_producto, _id_empresa, _material, _pureza, v_prefijo,
        _precio_venta_sugerido, _precio_compra_sugerido
      )
      RETURNING id INTO nuevo_id;
      RETURN nuevo_id;
    EXCEPTION
      WHEN unique_violation THEN
        -- ¿chocó por (id_producto, material, pureza) o por el prefijo?
        IF EXISTS (SELECT 1 FROM producto_variantes
                    WHERE id_producto = _id_producto
                      AND material = _material
                      AND pureza IS NOT DISTINCT FROM _pureza) THEN
          RAISE EXCEPTION 'Ya existe una variante % % para este producto', _material, coalesce(_pureza,'');
        END IF;
        v_intento := v_intento + 1;
        IF v_intento > 50 THEN
          RAISE EXCEPTION 'No se pudo generar un prefijo de SKU único a partir de "%"', v_prefijo_base;
        END IF;
    END;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.crear_venta_externa (
  _canal            text,
  _id_orden_externa text,
  _venta            jsonb,
  _items            jsonb
)
  RETURNS SETOF public.ventas
  LANGUAGE plpgsql
  AS $function$
DECLARE
    v_id_venta bigint;
    v_nro_comprobante text;
    v_item jsonb;
BEGIN
    IF _canal IS NULL OR _id_orden_externa IS NULL THEN
        RAISE EXCEPTION 'crear_venta_externa requiere _canal y _id_orden_externa';
    END IF;

    -- Camino rápido de idempotencia: si ya existe una venta para esta orden
    -- externa, devolverla tal cual, sin reprocesar ni volver a tocar stock.
    RETURN QUERY
        SELECT * FROM ventas WHERE origen = _canal AND id_orden_externa = _id_orden_externa;
    IF FOUND THEN
        RETURN;
    END IF;

    SELECT generar_nro_comprobante(
        (_venta->>'id_tipo_comprobante')::integer,
        _venta->>'serie',
        (_venta->>'id_sucursal')::integer
    ) INTO v_nro_comprobante;

    BEGIN
        INSERT INTO ventas (
            fecha, id_usuario, id_sucursal, id_empresa, id_cliente,
            monto_total, sub_total, total_impuestos, valor_impuesto,
            referencia_tarjeta, cantidad_productos,
            estado, nro_comprobante, origen, id_orden_externa
        ) VALUES (
            COALESCE((_venta->>'fecha')::timestamp, now()),
            (_venta->>'id_usuario')::bigint,
            (_venta->>'id_sucursal')::bigint,
            (_venta->>'id_empresa')::bigint,
            (_venta->>'id_cliente')::bigint,
            (_venta->>'monto_total')::numeric,
            COALESCE((_venta->>'sub_total')::numeric, (_venta->>'monto_total')::numeric),
            COALESCE((_venta->>'total_impuestos')::numeric, 0),
            COALESCE((_venta->>'valor_impuesto')::numeric, 0),
            COALESCE(_venta->>'referencia_tarjeta', '-'),
            COALESCE(jsonb_array_length(_items), 0),
            'confirmada',
            v_nro_comprobante,
            _canal,
            _id_orden_externa
        )
        RETURNING id INTO v_id_venta;
    EXCEPTION WHEN unique_violation THEN
        -- Otra llamada concurrente (ej. reintento de webhook llegado casi al
        -- mismo tiempo) ya insertó esta misma orden externa: devolver esa
        -- fila en vez de duplicar la venta.
        RETURN QUERY
            SELECT * FROM ventas WHERE origen = _canal AND id_orden_externa = _id_orden_externa;
        RETURN;
    END;

    -- Insertar cada ítem. El trigger validarstock (ya corregido en la Fase 1)
    -- descuenta el stock de forma atómica y lanza excepción si no alcanza;
    -- al ser todo una sola función, esa excepción revierte también el
    -- INSERT de la venta y los ítems ya insertados en esta misma llamada.
    FOR v_item IN SELECT * FROM jsonb_array_elements(_items)
    LOOP
        INSERT INTO detalle_venta (
            id_venta, id_producto, cantidad, precio_venta,
            precio_compra, descripcion, total, id_sucursal, id_almacen
        ) VALUES (
            v_id_venta,
            (v_item->>'id_producto')::bigint,
            (v_item->>'cantidad')::numeric,
            (v_item->>'precio_venta')::numeric,
            (v_item->>'precio_compra')::numeric,
            v_item->>'descripcion',
            (v_item->>'cantidad')::numeric * (v_item->>'precio_venta')::numeric,
            (_venta->>'id_sucursal')::bigint,
            (v_item->>'id_almacen')::bigint
        );
    END LOOP;

    RETURN QUERY SELECT * FROM ventas WHERE id = v_id_venta;
END;
$function$;

CREATE OR REPLACE FUNCTION public.crearcredencialesuser (
  email text,
  pass  text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  AS $function$
declare
   user_id uuid;
begin
   user_id := gen_random_uuid();
   insert into auth.users (
      id, 
      email, 
      encrypted_password, 
      raw_app_meta_data, 
      created_at, 
      updated_at, -- Incluye el campo updated_at
      instance_id, 
      aud, 
      role, 
      confirmation_token, 
      email_change, 
      email_change_token_new, 
      recovery_token, 
      phone_change, 
      email_confirmed_at
   )
   values (
      user_id,
      email,
      crypt(pass, gen_salt('bf')),
      jsonb_build_object('provider', 'email', 'providers', array['email']),
      now(),
      now(), -- Asigna la hora actual a updated_at
      (SELECT instance_id FROM auth.users WHERE instance_id IS NOT NULL LIMIT 1),
      'authenticated',
      'authenticated',
      '', -- confirmation_token
      '', -- email_change
      '', -- email_change_token_new
      '', -- recovery_token
      '', -- phone_change
      now()
   );
   return user_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.dashboardcajasporsucursalyventas (
  _id_empresa integer
)
  RETURNS TABLE (
    sucursal_nombre  text,
    caja_descripcion text,
    fecha_creacion   timestamp without time zone,
    total_ventas     numeric,
    estadocaja       integer,
    direccionfiscal  text,
    idcaja           integer,
    idsucursal       integer,
    delete           boolean
  )
  LANGUAGE sql
  AS $function$
WITH cierres_agrupados AS (
    SELECT
        cc.id_caja,
        MAX(cc.estado) AS estado,
        SUM(COALESCE(v.monto_total, 0)) AS total_ventas
    FROM
        cierrecaja cc
    LEFT JOIN
        ventas v
    ON
        cc.id = v.id_cierre_caja
    GROUP BY
        cc.id_caja
),
cajas_agrupadas AS (
    SELECT
        c.id AS id_caja,
        c.descripcion AS caja_descripcion,
        c.fecha_creacion,
        COALESCE(cg.total_ventas, 0) AS total_ventas,
        COALESCE(cg.estado, 2) AS estado
        
        
    FROM
        caja c
    LEFT JOIN
        cierres_agrupados cg
    ON
        c.id = cg.id_caja
)
SELECT
    s.nombre AS sucursal_nombre,
    ca.caja_descripcion,
    ca.fecha_creacion,
    ca.total_ventas,
    ca.estado AS estadocaja,
    s.direccion_fiscal as direccion_fiscal,
    ca.id_caja as idcaja,
    s.id as idsucursal,
    s.delete as delete


FROM
    sucursales s
INNER JOIN
    caja c
ON
    s.id = c.id_sucursal
LEFT JOIN
    cajas_agrupadas ca
ON
    c.id = ca.id_caja
WHERE
    s.id_empresa = _id_empresa
GROUP BY
    s.nombre, ca.caja_descripcion, ca.fecha_creacion, ca.total_ventas, ca.estado,ca.id_caja,s.id,s.direccion_fiscal,s.delete
ORDER BY
    s.nombre, ca.fecha_creacion;
$function$;

CREATE OR REPLACE FUNCTION public.dashboardsumarcantidaddetalleventa (
  _id_empresa   integer,
  _fecha_inicio timestamp without time zone,
  _fecha_fin    timestamp without time zone
)
  RETURNS numeric
  LANGUAGE sql
  AS $function$
SELECT 
    COALESCE(SUM(dv.cantidad), 0) -- Asegura que retorne 0 si no hay ventas
FROM 
    ventas AS v inner join detalle_venta dv on dv.id_venta=v.id
WHERE 
    v.id_empresa = _id_empresa
   AND DATE(v.fecha) >= DATE(_fecha_inicio) -- Convierte a solo fecha
  AND DATE(v.fecha) <= DATE(_fecha_fin);   -- Convierte a solo fecha
$function$;

CREATE OR REPLACE FUNCTION public.dashboardsumargananciadetalleventa (
  _id_empresa   integer,
  _fecha_inicio timestamp without time zone,
  _fecha_fin    timestamp without time zone
)
  RETURNS numeric
  LANGUAGE sql
  AS $function$
SELECT 
    COALESCE(SUM(dv.total - dv.cantidad*precio_compra), 0) -- Asegura que retorne 0 si no hay ventas
FROM 
    ventas AS v inner join detalle_venta dv on dv.id_venta=v.id
WHERE 
    v.id_empresa = _id_empresa
   AND DATE(v.fecha) >= DATE(_fecha_inicio) -- Convierte a solo fecha
  AND DATE(v.fecha) <= DATE(_fecha_fin);   -- Convierte a solo fecha
$function$;

CREATE OR REPLACE FUNCTION public.dashboardsumarventaporempresa (
  _id_empresa   integer,
  _fecha_inicio timestamp without time zone,
  _fecha_fin    timestamp without time zone
)
  RETURNS numeric
  LANGUAGE sql
  AS $function$
SELECT
    COALESCE(SUM(v.monto_total), 0) -- Asegura que siempre retorne 0 si no hay ventas
FROM
    ventas AS v
WHERE
    v.id_empresa = _id_empresa
    AND v.fecha >= _fecha_inicio
    AND v.fecha <= (_fecha_fin + INTERVAL '1 day' - INTERVAL '1 second'); -- Incluye el final del día
$function$;

CREATE OR REPLACE FUNCTION public.dashboardsumarventasporempresa (
  _id_empresa   integer,
  _fecha_inicio timestamp without time zone,
  _fecha_fin    timestamp without time zone
)
  RETURNS numeric
  LANGUAGE sql
  AS $function$
SELECT 
    COALESCE(SUM(v.monto_total), 0) -- Asegura que retorne 0 si no hay ventas
FROM 
    ventas AS v
WHERE 
    v.id_empresa = _id_empresa
   AND DATE(v.fecha) >= DATE(_fecha_inicio) -- Convierte a solo fecha
  AND DATE(v.fecha) <= DATE(_fecha_fin);   -- Convierte a solo fecha
$function$;

CREATE OR REPLACE FUNCTION public.dashboardsumarventasporempresaperiodoanterior (
  _id_empresa   integer,
  _fecha_inicio timestamp without time zone,
  _fecha_fin    timestamp without time zone
)
  RETURNS numeric
  LANGUAGE sql
  AS $function$
SELECT 
