$function$;

CREATE OR REPLACE FUNCTION public.dashboardtop5productosmasvendidos (
  _id_empresa   integer,
  _fecha_inicio timestamp without time zone,
  _fecha_fin    timestamp without time zone
)
  RETURNS TABLE (
    id_producto     integer,
    nombre_producto text,
    total_vendido   numeric,
    porcentaje      numeric
  )
  LANGUAGE sql
  AS $function$
WITH top_productos AS (
    SELECT
        dv.id_producto,
        p.nombre AS nombre_producto,
        SUM(dv.cantidad) AS total_vendido
    FROM
        detalle_venta AS dv
    INNER JOIN
        ventas AS v
    ON
        dv.id_venta = v.id
    INNER JOIN
        productos AS p
    ON
        dv.id_producto = p.id
    WHERE
        v.id_empresa = _id_empresa
       AND DATE(v.fecha) >= DATE(_fecha_inicio) -- Convierte a solo fecha
  AND DATE(v.fecha) <= DATE(_fecha_fin)   -- Convierte a solo fecha
    GROUP BY
        dv.id_producto, p.nombre
    ORDER BY
        total_vendido DESC
    LIMIT 5
),
total_general AS (
    SELECT
        SUM(total_vendido) AS total
    FROM
        top_productos
)
SELECT
    tp.id_producto,
    tp.nombre_producto,
    tp.total_vendido,
    ROUND((tp.total_vendido / tg.total) * 100, 2) AS porcentaje
FROM
    top_productos tp,
    total_general tg;
$function$;

CREATE OR REPLACE FUNCTION public.dashboartotalventasconfechas (
  _id_empresa   integer,
  _fecha_inicio timestamp without time zone,
  _fecha_fin    timestamp without time zone
)
  RETURNS TABLE (
    fecha        date,
    total_ventas numeric
  )
  LANGUAGE sql
  AS $function$
SELECT
    DATE(v.fecha) AS fecha, -- Agrupa por la fecha (sin tiempo)
    COALESCE(SUM(v.monto_total), 0) AS total_ventas -- Calcula el total de ventas
FROM
    ventas AS v
WHERE
    v.id_empresa = _id_empresa -- Filtra por empresa
    AND DATE(v.fecha) >= DATE(_fecha_inicio) -- Convierte a solo fecha
    AND DATE(v.fecha) <= DATE(_fecha_fin)   -- Convierte a solo fecha
GROUP BY
    DATE(v.fecha) -- Agrupa por fecha
ORDER BY
    fecha; -- Ordena por fecha
$function$;

CREATE OR REPLACE FUNCTION public.dashboartotalventasxmetodopago (
  _id_empresa   integer,
  _fecha_inicio timestamp without time zone,
  _fecha_fin    timestamp without time zone
)
  RETURNS TABLE (
    fecha        date,
    metodo_pago  text,
    total_ventas numeric
  )
  LANGUAGE sql
  AS $function$
SELECT
    DATE(mc.fecha_movimiento) AS fecha, -- Agrupa por la fecha (sin tiempo)
    mp.nombre AS metodo_pago, -- Nombre del método de pago
    COALESCE(SUM(mc.monto), 0) AS total_ventas -- Suma el total de ventas
FROM
    ventas AS v
INNER JOIN
    movimientos_caja AS mc
ON
    v.id = mc.id_ventas -- Relación entre ventas y movimientos de caja
INNER JOIN
    metodos_pago AS mp
ON
    mc.id_metodo_pago = mp.id -- Relación con métodos de pago
WHERE
    v.id_empresa = _id_empresa -- Filtra por empresa
    AND DATE(mc.fecha_movimiento) >= DATE(_fecha_inicio) -- Filtra por fecha de inicio
    AND DATE(mc.fecha_movimiento) <= DATE(_fecha_fin) -- Filtra por fecha de fin
    AND mc.id_ventas IS NOT NULL
GROUP BY
    DATE(mc.fecha_movimiento), mp.nombre -- Agrupa por fecha y método de pago
ORDER BY
    fecha asc; -- Ordena por fecha y luego por total de ventas
$function$;

CREATE OR REPLACE FUNCTION public.deletedetalleventa()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
BEGIN
  -- Si la cantidad es igual a 0, elimina el registro antes del UPDATE
  IF NEW.cantidad = 0 THEN
    DELETE FROM detalle_venta WHERE id = NEW.id;
    
  END IF;

  RETURN NEW; -- Continuar el flujo si la cantidad no es 0
END;
$function$;

CREATE OR REPLACE FUNCTION public.devolver_pieza (
  _id_pieza   integer,
  _id_empresa integer,
  _id_usuario integer,
  _destino    text,
  _nota       text
)
  RETURNS void
  LANGUAGE plpgsql
  AS $function$
DECLARE v_ant text;
BEGIN
  IF coalesce(_destino,'disponible') NOT IN ('disponible','danada') THEN
    RAISE EXCEPTION 'destino inválido: % (usar disponible | danada)', _destino;
  END IF;

  SELECT estado INTO v_ant FROM piezas_inventario
   WHERE id = _id_pieza AND id_empresa = _id_empresa FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pieza % no encontrada', _id_pieza; END IF;
  IF v_ant <> 'vendida' THEN
    RAISE EXCEPTION 'La pieza % no está vendida (estado %)', _id_pieza, v_ant;
  END IF;

  UPDATE piezas_inventario
     SET estado = coalesce(_destino,'disponible'),
         id_detalle_venta = NULL, id_venta_reserva = NULL,
         nota = coalesce(_nota, nota)
   WHERE id = _id_pieza;

  INSERT INTO movimientos_piezas (id_pieza, id_empresa, tipo, estado_anterior, estado_nuevo, id_usuario, notas)
  VALUES (_id_pieza, _id_empresa, 'devolucion', 'vendida', coalesce(_destino,'disponible'), _id_usuario, _nota);
END;
$function$;

CREATE OR REPLACE FUNCTION public.devolverstockaleliminardv()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
BEGIN
    -- Verificar si el producto tiene inventario gestionado
    IF (SELECT p.maneja_inventarios FROM productos p WHERE p.id = OLD.id_producto) THEN
        -- Incrementar el stock correspondiente en el almacén
        UPDATE stock
        SET stock = stock + OLD.cantidad
        WHERE id_producto = OLD.id_producto
          AND id_almacen = OLD.id_almacen;
    END IF;

    -- Continuar con la operación de eliminación
    RETURN OLD;
END;
$function$;

