$function$;

CREATE OR REPLACE FUNCTION public.obtenertotalescaja (
  p_id_caja integer
)
  RETURNS TABLE (
    total_ventas          numeric,
    total_ingresos        numeric,
    total_egresos         numeric,
    total_ventas_efectivo numeric,
    total_ventas_credito  numeric,
    total_ventas_tarjeta  numeric
  )
  LANGUAGE plpgsql
  AS $function$
BEGIN
 RETURN QUERY
    SELECT
        -- Subconsulta para evitar duplicación de ventas
        (SELECT COALESCE(SUM(v.monto_total), 0)
         FROM ventas v
         WHERE v.id_caja = p_id_caja  AND v.estado = 'confirmada'
           AND v.fecha BETWEEN cc.fechainicio AND NOW()) AS total_ventas,

        -- Subconsulta para sumar solo los ingresos
        (SELECT COALESCE(SUM(isc.monto), 0)
         FROM ingresos_salidas_caja isc
         WHERE isc.id_caja = p_id_caja 
           AND isc.tipo = 'ingreso'
           AND isc.fecha BETWEEN cc.fechainicio AND NOW()) AS total_ingresos,

        -- Subconsulta para sumar solo los egresos
        (SELECT COALESCE(SUM(isc.monto), 0)
         FROM ingresos_salidas_caja isc
         WHERE isc.id_caja = p_id_caja 
           AND isc.tipo = 'salida'
           AND isc.fecha BETWEEN cc.fechainicio AND NOW()) AS total_egresos,

        -- Total de ventas en efectivo
        (SELECT COALESCE(SUM(v.monto_total), 0)
         FROM ventas v
         WHERE v.id_caja = p_id_caja
           AND v.efectivo > 0
           AND v.estado = 'confirmada'
           AND v.fecha BETWEEN cc.fechainicio AND NOW()) AS total_ventas_efectivo,

        -- Total de ventas en crédito
        (SELECT COALESCE(SUM(v.monto_total), 0)
         FROM ventas v
         WHERE v.id_caja = p_id_caja
           AND v.credito > 0
           AND v.estado = 'confirmada'
           AND v.fecha BETWEEN cc.fechainicio AND NOW()) AS total_ventas_credito,

        -- Total de ventas en tarjeta
        (SELECT COALESCE(SUM(v.monto_total), 0)
         FROM ventas v
         WHERE v.id_caja = p_id_caja
           AND v.tarjeta > 0
           AND v.estado = 'confirmada'
           AND v.fecha BETWEEN cc.fechainicio AND NOW()) AS total_ventas_tarjeta   

    FROM cierrecaja cc
    WHERE cc.id_caja = p_id_caja;
END;
$function$;

CREATE OR REPLACE FUNCTION public.pos_buscar_pieza (
  _codigo     text,
  _id_empresa integer
)
  RETURNS TABLE (
    id_pieza     bigint,
    id_variante  bigint,
    id_producto  bigint,
    producto     text,
    categoria    text,
    material     text,
    pureza       text,
    sku          text,
    barcode      text,
    peso         numeric,
    costo        numeric,
    precio_venta numeric,
    estado       text,
    id_almacen   bigint
  )
  LANGUAGE sql
  STABLE
  AS $function$
  SELECT pi.id, pi.id_variante, pi.id_producto,
         p.nombre, c.nombre, v.material, v.pureza,
         pi.sku, pi.barcode, pi.peso, pi.costo, pi.precio_venta, pi.estado, pi.id_almacen
    FROM piezas_inventario pi
    JOIN producto_variantes v ON v.id = pi.id_variante
    JOIN productos p          ON p.id = pi.id_producto
    LEFT JOIN categorias c    ON c.id = p.id_categoria
   WHERE pi.id_empresa = _id_empresa
     AND (lower(pi.barcode) = lower(btrim(_codigo))
          OR lower(pi.sku) = lower(btrim(_codigo)))
   LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.reducirstock (
  _id      integer,
  cantidad numeric
)
  RETURNS void
  LANGUAGE plpgsql
  AS $function$
BEGIN
    UPDATE stock
       SET stock = stock - cantidad
     WHERE id = _id
       AND stock >= cantidad;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Stock insuficiente para este producto';
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.report_stock_bajo_minimo (
  sucursal_id integer,
  almacen_id  integer
)
  RETURNS TABLE (
    codigo_articulo      text,
    descripcion_articulo text,
    stock                numeric,
    stock_minimo         numeric,
    precio_costo         numeric,
    total                numeric
  )
  LANGUAGE sql
  AS $function$
SELECT 
    p.codigo_interno AS codigo_articulo,
    p.nombre AS descripcion_articulo,
    s.stock,
    s.stock_minimo,
    p.precio_compra AS precio_costo,
    (s.stock * p.precio_compra) AS total
FROM stock s
INNER JOIN almacen a ON s.id_almacen = a.id
INNER JOIN productos p ON s.id_producto = p.id
WHERE a.id_sucursal = sucursal_id
AND a.id = almacen_id
AND s.stock < s.stock_minimo;  -- 🔥 SOLO PRODUCTOS CON STOCK BAJO MÍNIMO
$function$;

CREATE OR REPLACE FUNCTION public.report_stock_por_almacen_sucursal (
  sucursal_id integer,
  almacen_id  integer
)
  RETURNS TABLE (
    codigo_articulo      text,
    descripcion_articulo text,
    stock                numeric,
    precio_costo         numeric,
    total                numeric
  )
  LANGUAGE sql
  AS $function$
SELECT 
    p.codigo_interno AS codigo_articulo,
    p.nombre AS descripcion_articulo,
    s.stock,
    p.precio_compra AS precio_costo,
    (s.stock * p.precio_compra) AS total
FROM stock s
INNER JOIN almacen a ON s.id_almacen = a.id
INNER JOIN productos p ON s.id_producto = p.id
WHERE a.id_sucursal = sucursal_id
AND a.id = almacen_id;
$function$;

CREATE OR REPLACE FUNCTION public.report_ventas_por_sucursal (
  sucursal_id  integer,
  fecha_inicio date,
  fecha_fin    date
)
  RETURNS TABLE (
    id_venta           integer,
    fecha              timestamp without time zone,
    monto_total        numeric,
    total_impuestos    numeric,
    subtotal           numeric,
    saldo              numeric,
    pago_con           text,
    cantidad_productos integer,
    id_usuario         integer,
    cajero             text,
    id_cliente         integer,
    estado             text
  )
  LANGUAGE sql
  AS $function$
SELECT 
    v.id AS id_venta,
    (v.fecha) AS fecha,  -- 🔥 Se convierte a solo fecha
    v.monto_total,
    v.total_impuestos,
    v.sub_total AS subtotal,
    v.saldo,
    v.pago_con,
    v.cantidad_productos,
    v.id_usuario,
    u.nombres AS cajero,
    v.id_cliente,
    v.estado
FROM ventas v
INNER JOIN usuarios u ON v.id_usuario = u.id
WHERE v.id_sucursal = sucursal_id
AND DATE(v.fecha) BETWEEN fecha_inicio AND fecha_fin; -- 🔥 Se filtra solo por día
$function$;

CREATE OR REPLACE FUNCTION public.reservar_pieza (
  _id_pieza   integer,
  _id_venta   integer,
  _id_empresa integer,
  _id_usuario integer
)
  RETURNS void
  LANGUAGE plpgsql
  AS $function$
BEGIN
  UPDATE piezas_inventario
     SET estado = 'reservada', id_venta_reserva = _id_venta, updated_at = now()
   WHERE id = _id_pieza
     AND id_empresa = _id_empresa
     AND estado = 'disponible';

  IF FOUND THEN
    INSERT INTO movimientos_piezas (id_pieza, id_empresa, tipo, estado_anterior, estado_nuevo,
                                    id_referencia, referencia_tipo, id_usuario, notas)
    VALUES (_id_pieza, _id_empresa, 'reserva', 'disponible', 'reservada',
            _id_venta, 'venta', _id_usuario, 'reserva desde el POS');
    RETURN;
  END IF;

  -- Ya estaba reservada por ESTA misma venta -> idempotente, no es error.
  IF EXISTS (SELECT 1 FROM piezas_inventario
              WHERE id = _id_pieza AND estado = 'reservada'
                AND id_venta_reserva = _id_venta) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'La pieza % ya no está disponible', _id_pieza;
END;
$function$;

CREATE OR REPLACE FUNCTION public.setdefaultserializacion (
  _id          integer,
  _id_sucursal integer
)
  RETURNS void
  LANGUAGE plpgsql
  AS $function$
begin 
  UPDATE serializacion_comprobantes
  SET por_default = false
   where sucursal_id=_id_sucursal;

    UPDATE serializacion_comprobantes
    SET por_default = true
     WHERE id = _id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sumarefectivosinventasmovcierrecaja (
  _id_cierre_caja integer
)
  RETURNS TABLE (
    tipo_movimiento text,
    monto           numeric
  )
  LANGUAGE sql
  AS $function$
SELECT 
   mc.tipo_movimiento,SUM(mc.monto) as monto
FROM 
  movimientos_caja AS mc
INNER JOIN 
  cierrecaja AS cc 
ON 
  mc.id_cierre_caja = cc.id
inner join metodos_pago as mp 
on
  mc.id_metodo_pago = mp.id  
WHERE 
  mp.nombre = 'Efectivo' and mc.id_ventas is null
  AND mc.id_cierre_caja = _id_cierre_caja and cc.estado=0
group by mc.tipo_movimiento
$function$;

CREATE OR REPLACE FUNCTION public.sumarnoefectivosinventasmovcierrecaja (
  _id_cierre_caja integer
)
  RETURNS TABLE (
    tipo_movimiento text,
    monto           numeric,
    metodo          text
  )
  LANGUAGE sql
  AS $function$
SELECT 
   mc.tipo_movimiento,SUM(mc.monto) as monto, mp.nombre as metodo
FROM 
  movimientos_caja AS mc
INNER JOIN 
  cierrecaja AS cc 
ON 
  mc.id_cierre_caja = cc.id
inner join metodos_pago as mp 
on
  mc.id_metodo_pago = mp.id  
WHERE 
  mp.nombre != 'Efectivo' and mc.id_ventas is null
  AND mc.id_cierre_caja = _id_cierre_caja and cc.estado=0
group by mc.tipo_movimiento, mp.nombre
$function$;

CREATE OR REPLACE FUNCTION public.sumarventasmetodopagomovcierrecaja (
  _id_cierre_caja integer
)
  RETURNS TABLE (
    metodo_pago text,
    monto       numeric
  )
  LANGUAGE sql
  AS $function$
select mp.nombre as metodo_pago, SUM(CASE WHEN mp.nombre='Efectivo' THEN mc.monto - mc.vuelto ELSE mc.monto END ) as monto from
movimientos_caja as mc
inner join cierrecaja as cc 
on
mc.id_cierre_caja = cc.id
inner join metodos_pago as mp
on mc.id_metodo_pago = mp.id
where mc.id_ventas is not  null
and mc.id_cierre_caja = _id_cierre_caja and cc.estado = 0
group by mp.nombre

$function$;

CREATE OR REPLACE FUNCTION public.sumarventasporempresa (
  _id_empresa   integer,
  _fecha_inicio timestamp without time zone,
  _fecha_fin    timestamp without time zone
)
  RETURNS numeric
  LANGUAGE sql
  AS $function$
SELECT 
    COALESCE(SUM(v.monto_total), 0) -- Asegura que retorne 0 si no hay ventas
FROM 
    ventas AS v
WHERE 
    v.id_empresa = _id_empresa
    AND v.fecha >= _fecha_inicio
    AND v.fecha <= _fecha_fin;
$function$;

CREATE OR REPLACE FUNCTION public.updateuseinventariosproductos()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
begin
 update productos
 set maneja_inventarios=false
 where id=old.id_producto;
 return old;
end
$function$;

CREATE OR REPLACE FUNCTION public.validarstock()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
BEGIN
    IF (SELECT p.maneja_inventarios FROM productos p WHERE p.id = NEW.id_producto) THEN

        -- Incremento de cantidad sobre un detalle_venta existente (UPDATE)
        IF TG_OP = 'UPDATE' AND NEW.cantidad > OLD.cantidad THEN
            UPDATE stock
               SET stock = stock - (NEW.cantidad - OLD.cantidad)
             WHERE id_producto = NEW.id_producto
               AND id_almacen = NEW.id_almacen
               AND stock >= (NEW.cantidad - OLD.cantidad);

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Stock insuficiente para el producto %', NEW.descripcion;
            END IF;

            INSERT INTO movimientos_stock (id_almacen, id_producto, tipo_movimiento, cantidad, fecha, detalle, origen)
            VALUES (NEW.id_almacen, NEW.id_producto, 'salida', NEW.cantidad, now(), 'se edito el detalle de venta', 'ventas');
        END IF;

        -- Decremento de cantidad (se devuelve stock): no requiere chequeo,
        -- sumar siempre es seguro, no hay forma de que "falle por falta de stock".
        IF TG_OP = 'UPDATE' AND NEW.cantidad < OLD.cantidad THEN
            UPDATE stock
               SET stock = stock + (OLD.cantidad - NEW.cantidad)
             WHERE id_producto = NEW.id_producto
               AND id_almacen = NEW.id_almacen;

            INSERT INTO movimientos_stock (id_almacen, id_producto, tipo_movimiento, cantidad, fecha, detalle, origen)
            VALUES (NEW.id_almacen, NEW.id_producto, 'ingreso', NEW.cantidad, now(), 'se edito el detalle de venta', 'ventas');
        END IF;

        -- Nuevo ítem en la venta (INSERT)
        IF TG_OP = 'INSERT' THEN
            UPDATE stock
               SET stock = stock - NEW.cantidad
             WHERE id_producto = NEW.id_producto
               AND id_almacen = NEW.id_almacen
               AND stock >= NEW.cantidad;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Stock insuficiente para el producto %', NEW.descripcion;
            END IF;

            INSERT INTO movimientos_stock (id_almacen, id_producto, tipo_movimiento, cantidad, fecha, detalle, origen)
            VALUES (NEW.id_almacen, NEW.id_producto, 'ingreso', NEW.cantidad, now(), 'nuevo registro', 'ventas');
        END IF;

    END IF;

    RETURN NEW;
END;
$function$;

